@Scheduled(fixedDelay = 200)
@Transactional
void publishOutbox() {
    // chỉ một instance làm relay; lock tự nhả khi transaction kết thúc
    Boolean leader = jdbc.queryForObject("select pg_try_advisory_xact_lock(42)", Boolean.class);
    if (!Boolean.TRUE.equals(leader)) return;

    // đọc theo trạng thái, không theo high-water mark: dòng commit muộn vẫn được thấy ở lần sau
    List<OutboxRow> rows = jdbc.query("""
            select id, aggregateid, type, payload
            from outbox
            where published_at is null
            order by id
            limit 500""", OUTBOX_ROW);
    for (OutboxRow row : rows) {
        kafka.send("orders", row.aggregateId(), row.payload()).get(5, SECONDS); // ack rồi mới đánh dấu
    }
    jdbc.batchUpdate("update outbox set published_at = now() where id = ?",
            rows.stream().map(r -> new Object[] { r.id() }).toList());
}

